unsigned long * vcpu_spsr32 ( const struct kvm_vcpu * vcpu ) { cfs_time_t mode = * vcpu_cpsr ( vcpu ) & COMPAT_PSR_MODE_MASK ; switch ( mode ) { case COMPAT_PSR_MODE_SVC : mode = KVM_SPSR_SVC ; break ; case COMPAT_PSR_MODE_ABT : mode = KVM_SPSR_ABT ; break ; case COMPAT_PSR_MODE_UND : mode = KVM_SPSR_UND ; break ; case COMPAT_PSR_MODE_IRQ : mode = KVM_SPSR_IRQ ; break ; case COMPAT_PSR_MODE_FIQ : mode = KVM_SPSR_FIQ ; break ; default : BUG ( ) ; } return ( unsigned long * ) & vcpu_gp_regs ( vcpu ) -> spsr [ mode ] ; } 